import{R as t,e as r,f as e,U as a}from"./chunks/framework.ywem4qy5.js";const f=JSON.parse('{"title":"Migrating from Sprout Forms","description":"","frontmatter":{},"headers":[],"relativePath":"migrations/migrating-from-sprout-forms.md","filePath":"migrations/migrating-from-sprout-forms.md","lastUpdated":1775908585000}'),i={name:"migrations/migrating-from-sprout-forms.md"};function s(n,o,m,l,p,d){return r(),e("div",null,[...o[0]||(o[0]=[a('<h1 id="migrating-from-sprout-forms" tabindex="-1">Migrating from Sprout Forms <a class="header-anchor" href="#migrating-from-sprout-forms" aria-label="Permalink to &quot;Migrating from Sprout Forms&quot;">​</a></h1><p>If your existing site has forms, submissions and email notifications from <a href="https://sprout.barrelstrengthdesign.com/docs/forms/" target="_blank" rel="noreferrer">Sprout Forms</a>, it can be easily migrated over to Formie. Your existing content with Sprout Forms will not be touched.</p><p>To migrate your forms and form data, install Formie, and navigate to Formie → Settings → Migrations → Sprout Forms. You&#39;ll need to have Sprout Forms installed and enabled for this setting to appear.</p><p>You&#39;ll be shown a screen to select from any existing Sprout Forms forms. Select which ones you want to migrate, and hit &quot;Migrate Forms&quot;. The next screen will show you the result of the migration, detailing what forms, email notifications and submissions were copied across and what errors or exceptions were encountered.</p><p>Any form that is attempted to be imported with the same handle will have a number affixed to the form. So if you already have a Formie form with a handle <code>contactForm</code> and also have a <code>contactForm</code> in Sprout Forms, the migration tool will name this new form to <code>contactForm1</code>.</p><h2 id="support" tabindex="-1">Support <a class="header-anchor" href="#support" aria-label="Permalink to &quot;Support&quot;">​</a></h2><p>The following Sprout Forms fields are currently unsupported in Formie:</p><ul><li>Private Notes</li><li>Regular Expression</li></ul>',8)])])}const c=t(i,[["render",s]]);export{f as __pageData,c as default};
